import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;
  const root = new Group();
  const ownedGeometries = [];
  const ownedMaterials = [];
  const ownedTextures = [];
  const primitiveResults = [];
  const timelines = [];

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const gradientMaterial = new MeshBasicNodeMaterial();
  gradientMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.09, 0.09, 0.118),
      smoothstep(0.18, 0.82, uv().y)
    ),
    smoothstep(0.0, 1.0, uv().y)
  );
  gradientMaterial.side = ctx.THREE.DoubleSide;
  ownedMaterials.push(gradientMaterial);

  const backdropGeometry = new PlaneGeometry(7, 6);
  ownedGeometries.push(backdropGeometry);

  const backdrop = new Mesh(backdropGeometry, gradientMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const panelMaterial = new MeshBasicNodeMaterial({
    color: colors.ink
  });
  panelMaterial.map = null;
  panelMaterial.side = ctx.THREE.DoubleSide;
  ownedMaterials.push(panelMaterial);

  const panelGeometry = new PlaneGeometry(3.15, 1.42);
  ownedGeometries.push(panelGeometry);

  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.position.set(0.42, 0.05, 0);
  root.add(panel);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });
  accentMaterial.side = ctx.THREE.DoubleSide;
  ownedMaterials.push(accentMaterial);

  const accentGeometry = new PlaneGeometry(0.055, 0.92);
  ownedGeometries.push(accentGeometry);

  const accentBar = new Mesh(accentGeometry, accentMaterial);
  accentBar.position.set(-1.04, 0.05, 0.025);
  root.add(accentBar);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let textOffset = 0;

  for (const item of items) {
    const text = String(item.text ?? '');
    const typography = item.typography ?? {};
    const isHeadline = item.role === 'headline' || item.role === 'display';

    const textObject = ctx.fontAtlas.createText(text, {
      fontSize: typography.fontSize ?? (isHeadline ? 39 : 16),
      color: isHeadline ? colors.paper : colors.paper,
      align: 'left',
      letterSpacingPx: typography.letterSpacingPx
    });

    textObject.position.set(-0.84, 0.05 - textOffset, 0.04);
    root.add(textObject);
    textOffset += isHeadline ? 0.16 : 0.11;
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (!texture || !panelMaterial) return;
      panelMaterial.map = texture;
      panelMaterial.color.set(colors.paper);
      panelMaterial.needsUpdate = true;
      ownedTextures.push(texture);
    }).catch(() => {});
  }

  const entrance = gsap.timeline({
    paused: true,
    defaults: {
      overwrite: 'auto'
    }
  });

  entrance.fromTo(
    root.scale,
    { x: 0.985, y: 0.985, z: 0.985 },
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'power4.out'
    }
  );

  entrance.fromTo(
    root.position,
    { y: -0.18 },
    {
      y: 0,
      duration: 0.7,
      ease: 'power3.out'
    },
    0
  );

  entrance.play();
  timelines.push(entrance);

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler !== 'function') continue;

    const result = handler(root, primitive.params ?? {});
    if (result) {
      primitiveResults.push(result);
      if (result.timeline) timelines.push(result.timeline);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const timeline of timelines) {
      if (timeline?.kill) timeline.kill();
    }

    for (const result of primitiveResults) {
      if (result?.cleanup) result.cleanup();
    }

    for (const material of ownedMaterials) {
      if (material?.dispose) material.dispose();
    }

    for (const geometry of ownedGeometries) {
      if (geometry?.dispose) geometry.dispose();
    }

    for (const texture of ownedTextures) {
      if (texture?.dispose) texture.dispose();
    }

    root.clear();
  };

  return root;
}
